-- NEWER VGM SEGA/Atlus — Section 9 (Space Channel 5)
--
-- Source: reference/NEWER VGM Sound Sources - SEGAAtlus.csv lines 1155-1354.
-- 2 game records, ~194 usage rows.
--
-- This section is heavily sample-based. The Space Channel 5 soundtracks
-- pull from jazz, lounge, film score, and bossa nova classics — preserved
-- as 'Sample: <artist> - <track>' in raw_source. Notable cross-media
-- artists sampled include Quincy Jones, Lalo Schifrin, Elmer Bernstein,
-- John Williams (The Hunt, The Raptors Appear), Henry Mancini, Hugo
-- Montenegro, Duke Ellington, Dizzy Gillespie, and more.
--
-- Notable curiosities preserved verbatim per Rule 2:
--   - "Live Recording: Michael Jackson (Beatboxing)" — SC5 Part 2 T1257.
--     Documented contribution from Michael Jackson, who was a fan of the
--     original; sampled for "Save Space Michael the Office Chief!"
--   - "Interpolation: Hugo Montenegro - Wild Bike" (SC5 main row 1).
--   - "Sample: ? - Blue Danube" (SC5 Part 2 stuff_to_find T1341) —
--     contributor knows the song but not the recording artist.
--   - "? (Song Sample)" / "? (DJ Tool?)" rows preserved with that literal
--     uncertainty annotation in raw_source.
--   - The "Mororina♥" / "Coco★Tapioka" diacritical characters preserved
--     verbatim in the example columns.

INSERT OR IGNORE INTO manufacturers (name) VALUES
  ('Clavia'),
  ('Ninja Tune');

