  ((SELECT id FROM manufacturers WHERE name = 'Sound Ideas'   COLLATE NOCASE), 'Hanna-Barbera Sound FX Library',            'Sample Library'),
  ((SELECT id FROM manufacturers WHERE name = 'Sound Ideas'   COLLATE NOCASE), 'The General Series 6000',                   'Sample Library'),
  ((SELECT id FROM manufacturers WHERE name = 'EastWest'      COLLATE NOCASE), 'Quantum Leap Brass',                        'Sample Library'),
  ((SELECT id FROM manufacturers WHERE name = 'IK Multimedia' COLLATE NOCASE), 'SampleTank XL',                             'Instrument');

